export const TYPES=raw.map((a,id)=>({id,name:a[0],desc:a[1],kind:a[2],color:a[3],rarity:a[4],mass:a[5],radius:a[6],flatness:a[7],smoothness:a[8]}));
export const BASES=['AT','TA','GC','CG'];
export function makeStone(id,variation=true){const t=TYPES[id],factor=variation?.9+Math.random()*.2:1;const stone={...t,uid:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,mass:t.mass*factor,radius:t.radius*(.96+factor*.04),flatness:Math.min(.99,t.flatness*(variation?.95+Math.random()*.1:1)),smoothness:Math.min(.99,t.smoothness*(variation?.95+Math.random()*.1:1)),thickness:.008+(1-t.flatness)*.021,genes:Array.from({length:4},()=>BASES[Math.floor(Math.random()*4)]),level:0,history:[],collectedAt:Date.now(),best:0};return {...stone,outline:outlineOf(stone),outlineGene:outlineGeneOf(stone)};}
